function makeElder(){const g=new THREE.Group();g.position.set(3,0,7);scene.add(g);const robe=mat(0x746e58),hood=mat(0xd1b986);box(g,0,.9,0,.75,1.3,.52,robe);const h=new THREE.Mesh(new THREE.SphereGeometry(.3,8,7),skinMat);h.position.y=1.65;g.add(h);const cap=cone(g,0,1.98,0,.43,.55,hood,5);cap.rotation.y=.4;const mark=new THREE.Mesh(new THREE.OctahedronGeometry(.16),new THREE.MeshBasicMaterial({color:0xffd77e}));mark.position.y=2.35;g.add(mark);return g}const elder=makeElder();
const keys={},clock=new THREE.Clock();let started=false,health=100,chakra=100,xp=0,level=1,rogues=0,questStage=0,attackTimer=0,invuln=0,dashTime=0,dashCooldown=0,combo=0,comboWindow=0,playerSpeed=9,dialogueOpen=false,bossSpawned=false;const cooldown={q:0,e:0,r:0};
const ui={healthFill:document.querySelector('#healthFill'),healthText:document.querySelector('#healthText'),chakraFill:document.querySelector('#chakraFill'),chakraText:document.querySelector('#chakraText'),xpFill:document.querySelector('#xpFill'),level:document.querySelector('#level'),objectiveText:document.querySelector('#objectiveText'),objectiveCount:document.querySelector('#objectiveCount'),questTitle:document.querySelector('#questTitle'),questText:document.querySelector('#questText'),target:document.querySelector('#target'),targetName:document.querySelector('#targetName'),targetHealth:document.querySelector('#targetHealth'),toast:document.querySelector('#toast'),dialogue:document.querySelector('#dialogue'),dialogueText:document.querySelector('#dialogueText'),dialogueButton:document.querySelector('#dialogueButton'),location:document.querySelector('#locationText')};
function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=2.2}let toastTimer=0;
function refresh(){ui.healthFill.style.width=health+'%';ui.healthText.textContent=Math.ceil(health)+' / 100';ui.chakraFill.style.width=chakra+'%';ui.chakraText.textContent=Math.floor(chakra)+' / 100';ui.xpFill.style.width=(xp%100)+'%';ui.level.textContent='LVL '+String(level).padStart(2,'0');ui.objectiveCount.textContent=rogues+' / '+(questStage===0?3:5)}function award(amount){xp+=amount;while(xp>=100){xp-=100;level++;health=Math.min(100,health+30);chakra=100;showToast('LEVEL UP · CHAKRA CAPACITY RESTORED')}refresh()}
function acceptQuest(){if(questStage===0){questStage=1;rogues=0;ui.questTitle.textContent='THE OUTSKIRTS';ui.questText.textContent='Defeat the rogue shinobi troubling the old road. Explore the forest paths to find them.';ui.objectiveText.textContent='Rogues defeated';showToast('QUEST ACCEPTED · THE OUTSKIRTS')}else if(questStage===1&&rogues>=3){questStage=2;ui.questTitle.textContent='A DEEPER RIFT';ui.questText.textContent='A powerful presence has appeared in the cedar hollow. Track it down and survive.';ui.objectiveText.textContent='Defeat the Rift Warden';ui.objectiveCount.textContent='0 / 1';enemies.push(makeEnemy('boss',-25,-68));bossSpawned=true;showToast('NEW TALE · A DEEPER RIFT')}ui.dialogue.classList.remove('show');dialogueOpen=false}
function openElder(){if(!started)return;dialogueOpen=true;ui.dialogue.classList.add('show');if(questStage===0){ui.dialogueText.textContent='The old road has grown dangerous. Rogue shinobi are gathering near the cedar grove. Could you drive them away?';ui.dialogueButton.textContent='ACCEPT TASK · F'}else if(questStage===1&&rogues>=3){ui.dialogueText.textContent='Excellent work. But the rift has awakened something deeper in the cedar hollow. Find its guardian and end this threat.';ui.dialogueButton.textContent='CONTINUE · F'}else if(questStage>=2){ui.dialogueText.textContent='The village is safer because of you, shinobi. Keep exploring—the wilds still hold many secrets.';ui.dialogueButton.textContent='CLOSE · F'}else{ui.dialogueText.textContent='The rogue shinobi still roam the old road. Be careful out there—and keep your chakra close.';ui.dialogueButton.textContent='CLOSE · F'}}
function enemyDistance(e){return player.position.distanceTo(e.position)}function nearestEnemy(max=5){let best=null,d=max;for(const e of enemies){if(!e.userData.alive)continue;const de=enemyDistance(e);if(de<d){best=e;d=de}}return best}
function damageEnemy(e,amount,push=0){if(!e?.userData.alive)return;e.userData.hp-=amount;if(push){const dir=e.position.clone().sub(player.position).normalize();e.position.addScaledVector(dir,push)}if(e.userData.hp<=0){e.userData.hp=0;e.userData.alive=false;scene.remove(e);award(e.userData.type==='boss'?100:e.userData.type==='brute'?34:22);if(e.userData.type==='boss'){questStage=3;ui.questTitle.textContent='RIFTBOUND';ui.questText.textContent='The Rift Warden has fallen. The frontier is yours to explore—your legend is only beginning.';ui.objectiveText.textContent='Frontier secured';ui.objectiveCount.textContent='COMPLETE';showToast('RIFT WARDEN DEFEATED · QUEST COMPLETE')}else if(questStage===1){rogues++;ui.objectiveCount.textContent=rogues+' / 3';if(rogues===3)showToast('TASK COMPLETE · RETURN TO ELDER MIRA')}if(targetEnemy===e)targetEnemy=null}refresh()}
function melee(power=1){if(!started||dialogueOpen)return;const e=nearestEnemy(4.5);if(!e){attackTimer=.25;return}combo=comboWindow>0?(combo%3)+1:1;comboWindow=1.15;attackTimer=.28;damageEnemy(e,(combo===3?34:22)*power,combo===3?1.9:.7);targetEnemy=e;player.rotation.y=Math.atan2(e.position.x-player.position.x,e.position.z-player.position.z);if(combo===3){for(let i=0;i<8;i++){const p=new THREE.Mesh(new THREE.IcosahedronGeometry(.09),new THREE.MeshBasicMaterial({color:0xffcc75}));p.position.set(player.position.x,1+Math.random(),player.position.z);scene.add(p);const v=new THREE.Vector3(Math.random()-.5,Math.random()*.7,Math.random()-.5).multiplyScalar(5);particles.push({mesh:p,vel:v,life:.45})}}}
const particles=[];function burst(){if(!started||dialogueOpen)return;const e=nearestEnemy(8);if(chakra<20||cooldown.q>0){showToast(chakra<20?'NOT ENOUGH CHAKRA':'TECHNIQUE RECHARGING');return}chakra-=20;cooldown.q=3.1;refresh();if(e){damageEnemy(e,47,3);targetEnemy=e}for(let i=0;i<18;i++){const a=i/18*Math.PI*2,p=new THREE.Mesh(new THREE.OctahedronGeometry(.12+Math.random()*.1),new THREE.MeshBasicMaterial({color:0x78e6ed,transparent:true,opacity:.9}));p.position.set(player.position.x+Math.cos(a)*.8,1+Math.random(),player.position.z+Math.sin(a)*.8);scene.add(p);particles.push({mesh:p,vel:new THREE.Vector3(Math.cos(a)*6,Math.random()*2,Math.sin(a)*6),life:.5})}}
function shadowBurst(){if(!started||dialogueOpen)return;if(chakra<35||cooldown.e>0){showToast(chakra<35?'NOT ENOUGH CHAKRA':'TECHNIQUE RECHARGING');return}chakra-=35;cooldown.e=6;refresh();let hit=0;for(const e of enemies){if(e.userData.alive&&enemyDistance(e)<7){damageEnemy(e,42,2.4);hit++}}for(let i=0;i<34;i++){const a=Math.random()*6.28,r=Math.random()*6,p=new THREE.Mesh(new THREE.SphereGeometry(.11,5,4),new THREE.MeshBasicMaterial({color:i%2?0x9b75e8:0x72d9ea,transparent:true,opacity:.9}));p.position.set(player.position.x+Math.cos(a)*r,.3+Math.random()*2,player.position.z+Math.sin(a)*r);scene.add(p);particles.push({mesh:p,vel:new THREE.Vector3(Math.cos(a)*3,1+Math.random()*2,Math.sin(a)*3),life:.7})}showToast(hit?'SHADOW BURST · '+hit+' HIT'+(hit>1?'S':''):'SHADOW BURST')}
function riftSurge(){if(!started||dialogueOpen)return;if(chakra<55||cooldown.r>0){showToast(chakra<55?'NOT ENOUGH CHAKRA':'TECHNIQUE RECHARGING');return}chakra-=55;cooldown.r=15;health=Math.min(100,health+20);refresh();for(const e of enemies){if(e.userData.alive&&enemyDistance(e)<12)damageEnemy(e,85,5)}dashTime=.7;dashCooldown=1;showToast('RIFT SURGE · RESTORED +20 VITALITY')}
function dash(){if(!started||dashCooldown>0||dialogueOpen)return;dashTime=.22;dashCooldown=1.1;player.userData.lastDash=performance.now()/1000}
const keys={},mobileMove={forward:false,back:false,left:false,right:false};window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyQ')burst();if(e.code==='KeyE')shadowBurst();if(e.code==='KeyR')riftSurge();if(e.code==='Space'||e.code==='ShiftLeft'||e.code==='ShiftRight')dash();if(e.code==='KeyF'){if(dialogueOpen)acceptQuest();else if(player.position.distanceTo(elder.position)<4.2)openElder()}if(e.code==='Escape'&&dialogueOpen){ui.dialogue.classList.remove('show');dialogueOpen=false}});window.addEventListener('keyup',e=>keys[e.code]=false);canvas.addEventListener('pointerdown',e=>{if(e.button===0)melee()});document.querySelector('#start').addEventListener('click',()=>{started=true;document.querySelector('#overlay').classList.add('hide');showToast('WELCOME TO THE FRONTIER')});ui.dialogueButton.addEventListener('click',acceptQuest);
document.querySelectorAll('[data-move]').forEach(b=>{const k=b.dataset.move;const set=v=>mobileMove[k]=v;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);set(true)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>set(false)))});document.querySelectorAll('[data-act]').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();const a=b.dataset.act;if(a==='attack')melee();if(a==='q')burst();if(a==='e')shadowBurst();if(a==='dash')dash()}));
function updateTarget(){let best=null,d=19;for(const e of enemies){if(!e.userData.alive)continue;const dist=enemyDistance(e);if(dist<d){d=dist;best=e}}targetEnemy=best;if(best){ui.target.style.display='block';ui.targetName.textContent=best.userData.type==='boss'?'RIFT WARDEN':best.userData.type==='brute'?'ROGUE ENFORCER':'ROGUE SHINOBI';ui.targetHealth.style.width=Math.max(0,best.userData.hp/best.userData.max*100)+'%'}else ui.target.style.display='none'}
function minimap(){const c=mapCtx,w=144;c.clearRect(0,0,w,w);c.fillStyle='#182a2d';c.fillRect(0,0,w,w);c.strokeStyle='#756f58';c.lineWidth=7;c.beginPath();c.moveTo(72,144);c.lineTo(72,77);c.lineTo(49,58);c.lineTo(49,12);c.moveTo(71,83);c.lineTo(105,83);c.stroke();c.fillStyle='#889876';for(const [x,y] of [[37,42],[100,39],[39,86],[100,100],[117,59],[25,111],[72,28]]){c.beginPath();c.arc(x,y,5,0,Math.PI*2);c.fill()}c.fillStyle='#e2ba6e';c.fillRect(66,72,8,8);const px=72+player.position.x*.37,pz=80+player.position.z*.37;c.fillStyle='#81ebea';c.beginPath();c.arc(px,pz,4,0,Math.PI*2);c.fill();for(const e of enemies){if(!e.userData.alive)continue;const ex=72+e.position.x*.37,ez=80+e.position.z*.37;if(ex>2&&ex<142&&ez>2&&ez<142){c.fillStyle=e.userData.type==='boss'?'#d878e8':'#e66561';c.beginPath();c.arc(ex,ez,e.userData.type==='boss'?3.5:2,0,Math.PI*2);c.fill()}}}

